/opt/homebrew/bin/zsh -lc "rtk python3 -c \"import ast,json,pathlib; base=pathlib.Path('vault/specs/emr-driver-tracer/reference'); tree=ast.parse((base/'models.py').read_text()); data=json.loads((base/'audit-event.golden.json').read_text()); enums={}; fields=[]; ann={};
for node in tree.body:
    if isinstance(node, ast.ClassDef) and node.name in {'FailureClass','JobStatus','ActionOutcome'}:
        enums[node.name]={a.targets[0].id:a.value.value for a in node.body if isinstance(a, ast.Assign) and isinstance(a.value, ast.Constant)}
    if isinstance(node, ast.ClassDef) and node.name=='AuditEvent':
        for a in node.body:
            if isinstance(a, ast.AnnAssign) and isinstance(a.target, ast.Name):
                fields.append(a.target.id); ann[a.target.id]=ast.unparse(a.annotation)
print('AuditEvent fields:', fields); print('Golden keys:', list(data.keys())); print('Enums:', enums); print('Annotations:', ann); print('outcome valid:', data.get('outcome') in enums['ActionOutcome'].values()); print('failure null accepted by annotation:', ann.get('failure_class'))\""

